  if(form.id==='studio-photos-form'){await withForm(form,'studio-photos-status',async()=>{const next=structuredClone(state),photos=next.settings.studioPhotos||['assets/sala-estudio.webp','assets/rincon-estudio.webp','assets/cuencos-estudio.webp'];for(let i=0;i<3;i++){const file=form.elements['photo'+i].files[0];if(file){if(!file.type.startsWith('image/')||file.size>4000000)throw Error('Cada imagen debe pesar hasta 4 MB.');photos[i]=await storeFile(file);}}next.settings.studioPhotos=photos;if(!save(next))throw Error('No se pudieron guardar las fotos.');dirty=false;render();status('studio-photos-status','Fotografías guardadas.');});return;}
