 async function start(){try{const response=await fetch(new URL('defaults.json',BASE),{cache:'no-store'});if(!response.ok)throw Error();initial=await response.json();try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');state=saved?.version===1&&Array.isArray(saved.contents)&&saved.settings&&saved.member&&Array.isArray(saved.demoMembers)?saved:structuredClone(initial);}catch{state=structuredClone(initial);}if(state.assetRevision!==2){const replacements={'assets/yoga-hero.webp':'assets/instructora-cuencos.webp','assets/oceano.webp':'assets/cuencos-estudio.webp','assets/reflexion.webp':'assets/rincon-estudio.webp'};if(replacements[state.settings.heroImage])state.settings.heroImage=replacements[state.settings.heroImage];for(const c of state.contents){if(replacements[c.image])c.image=c.category==='yoga'?'assets/yoga-aereo.webp':replacements[c.image];}state.assetRevision=2;save();}if(state.visualRevision!==4){if(state.settings.logo==='assets/logo.webp')state.settings.logo='assets/logo-transparente.png';state.visualRevision=4;save();}if(state.managementRevision!==14){state.demoMembers=state.demoMembers.filter(m=>!/^Alumno de muestra/.test(m.name));if(state.settings.libraryTitle==='Elegí tu momento de bienestar')state.settings.libraryTitle='Nuestros espacios';state.managementRevision=14;save();}state.settings.showAmbient=state.settings.showAmbient!==false;await hydrate();readRoute();}catch{main.innerHTML='<div class="wrap section"><h1>No pudimos abrir la demo.</h1><p>Recargá la página para volver a intentar.</p></div>';}}
